        /// <summary>
        /// This method is used to update New_Message_Flag from 'Y' 
        /// to 'N' for logged in user.
        /// </summary>
        /// <param name="aiUserId"></param>

        public void UpdateNewMessageFlag(int aiUserId, int aiAcademicYrId)
        {
            string sUpdateStatement = " UPDATE  Message_Receiver_Details SET " +
                                        " Message_Receiver_Details.New_Message_Flag = N'" + Constants.C_NO + "'" +
                                        " FROM Message_Receiver_Details INNER JOIN " +
                                        " Message_Details ON " +
                                        " Message_Receiver_Details.Message_Details_Id = Message_Details.Message_Details_Id " +
                                        " WHERE (Message_Receiver_Details.Receiver_User_Id =" + aiUserId + ")" +
                                        " AND (Message_Receiver_Details.Is_Archive = N'" + Constants.C_NO + "') AND " +
                                        " (Message_Receiver_Details.New_Message_Flag = N'" + Constants.C_YES + "')" +
                                        " AND (Message_Receiver_Details.Is_DeletedFromReceiver = N'" + Constants.C_NO + "') AND " +
                                        " (Message_Details.academic_Year_Id =" + aiAcademicYrId + ")";
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
                oSQLServerDbUtility.ExecuteTransaction(sUpdateStatement);
        }


