        public static int GetMessageReceiverDetailsIdForSWCoordinator(int aiMessageId, int aiSchoolId)
        {
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                string sQuery = "SELECT Message_Receiver_Details_Id" +
                             " FROM Message_Receiver_Details " +
                             " WHERE Message_Details_Id =" + aiMessageId +
                             " AND Receiver_User_Id IN( SELECT User_Id " +
                                                        " FROM User_Master " +
                                                        " WHERE User_First_Name Like '%Software Coordinator%' " +
                                                        " AND School_Id=" + aiSchoolId +
                                                        " ) AND Is_Deleted='N'";
                //oSQLServerDbUtility.AddParameter("Message_Details_Id", aiMessageId, SqlDbType.Int);
                //oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                return oSQLServerDbUtility.PerformIntQueryOnSqlServer(sQuery);
            }
        }

