        /// </summary>
        /// <param name="aiSchoolId"></param>
        /// <param name="aiMessageId"></param>

        public List<MessageDetails> GetEmailAddressAndReceiverUserId(int aiSchoolId, int aiMessageId)
        {
            List<MessageDetails> lstMessageDetails = new List<MessageDetails>();
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("MessageId", aiMessageId, SqlDbType.Int);
                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetEmailAddresses"))
                {
                    if (oSqlDataReader != null)
                    {
                        while (oSqlDataReader.Read())
                        {
                            MessageDetails oMessageDetails = new MessageDetails
                            {
                                MessageReceiverDetailsId = oSqlDataReader["Message_Receiver_Details_Id"].ToInt(),
                                EmailAddress = oSqlDataReader["Email_Address"].ToString()
                            };
                            lstMessageDetails.Add(oMessageDetails);
                        }
                    }
                }
                return lstMessageDetails;
            }
        }

