        {
            string sFilter = CreateFilter(asFilter, asOperator, dtDate);
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("aiUserId", aiUserId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("sIsArch", "Y", SqlDbType.NVarChar);
                oSQLServerDbUtility.AddParameter("aiAcadYrId", aiAcadYrId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("Filter", asFilter, SqlDbType.NVarChar);
                oSQLServerDbUtility.AddParameter("Operator", sFilter, SqlDbType.NVarChar);
                if (dtDate != DateTime.MinValue)
                    oSQLServerDbUtility.AddParameter("FilterDate", dtDate, SqlDbType.DateTime);
                DataTable oDataTable = oSQLServerDbUtility.ExecuteStoredProcedureAndGetDataTable("usp_GetCntOfUnreadMsgs");
                return Convert.ToInt32(oDataTable.Rows[0][0]);
            }
        }

        public List<ReadReceiptDetails> GetAllReadReceiptDetails(int aiMessageDetailsId, int aiSchoolId, int aiAcademicYearId)
        {
            List<ReadReceiptDetails> lstReadReceiptDetails = new List<ReadReceiptDetails>();
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", aiAcademicYearId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("MessageDetailId", aiMessageDetailsId, SqlDbType.Int);
                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetReadReceiptDetails"))
                {
                    while (oSqlDataReader.Read())
                    {
                        lstReadReceiptDetails.Add(new ReadReceiptDetails
                        {
                            ClassName = oSqlDataReader["ClassName"].ToString(),
                            ReadingDatetime = Convert.ToDateTime(oSqlDataReader["ReadingDatetime"]).ToString("dd-MMM-yyyy hh:mm tt"),
                            UserId = Convert.ToInt32(oSqlDataReader["UserId"]),
                            UserName = Convert.ToString(oSqlDataReader["UserName"]),
                            UserRole = Convert.ToString(oSqlDataReader["UserRole"])
                        });
                    }
                }
            }
            return lstReadReceiptDetails;
        }

        /// <summary>
        /// This method is used for create operator Filter.
        /// </summary>
        /// <param name="asFilter"></param>
        /// <param name="asOperator"></param>
        /// <param name="dtDate"></param>
        /// <returns></returns>
        private string CreateFilter(string asFilter, string asOperator, DateTime dtDate)
        {
            string sFilter = "";
            if (asFilter == string.Empty && dtDate == DateTime.MinValue)
                sFilter = string.Empty;
            else
            {
                List<String> operators = GetOperators().Where(opr => opr.Value.ToString() == asOperator).Select(opr => opr.Text).ToList();
                sFilter = operators.Count > Constants.I_ZERO ? operators.First() : string.Empty;
            }
            return sFilter;
        }

        /// <summary>
        /// This method is used to get Operator list.
        /// </summary>
        public static List<Operator> GetOperators()
        {
            List<Operator> olstOperators = new List<Operator>();
            olstOperators.Add(new Operator { Value = 1, Text = "=" });
            olstOperators.Add(new Operator { Value = 2, Text = "<" });
            olstOperators.Add(new Operator { Value = 3, Text = "<=" });
            olstOperators.Add(new Operator { Value = 4, Text = ">" });
            olstOperators.Add(new Operator { Value = 5, Text = ">=" });
            return olstOperators;
        }

    }
}
